// EXAMPLE ONLY — the real provision.h is generated by tools/blob2header.py from a
// `prius-satkey new NAME --transport ble -o blob.json` blob and is git-ignored.
// These keys are all-zero placeholders: a satellite built with them boots, scans and
// connects, but the car refuses it ("fp does not match" / "bad signature").
#pragma once
#include <stdint.h>

#define PROV_SAT_ID      300
#define PROV_NAME        "example"
#define PROV_TRANSPORT   "ble"
#define PROV_FP          "aaaaaaaaaaaaaaaaaaaaaaaaaa"
#define PROV_PUBKEY_B64  "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="
#define PROV_CAR_FP      "aaaaaaaaaaaaaaaaaaaaaaaaaa"
#define PROV_CAR_ADDR    "02:00:E8:51:02:58"   // "" = any advertiser of the service
#define PROV_CERT_JSON   ""                    // "" = no cert (needs enrolment)

static const uint8_t PROV_PRIVKEY[32] = {0};
static const uint8_t PROV_PUBKEY[32]  = {0};
static const uint8_t PROV_CAR_PUB[32] = {0};
